\begin{frame}[shrink=4]{Logit Attribution}
\begin{center}
\includegraphics[width=0.9\textwidth,height=0.75\textheight,keepaspectratio]{figures/elhage2021/attention_patter_and_logit_attribution.png}
\end{center}

