\begin{frame}{Activation Patching}
\centering
\begin{tikzpicture}[x=1cm,y=1cm,blk/.style={draw=black!40,fill=black!5,rounded corners=2pt,minimum width=1.1cm,minimum height=0.55cm,font=\scriptsize}]
\node[font=\small\bfseries,anchor=west] at (-4.5,2.6) {clean};
\patchrun{2.0}{When Mary and John went to the store, John gave a drink to}{c}
\patchbars{2.0}{2.2}{0.2}
\begin{scope}[visible on=<2->]
\node[font=\small\bfseries,anchor=west] at (-4.5,0.6) {corrupted};
\patchrun{0.0}{When Mary and John went to the store, \textcolor{fd}{Mary} gave a drink to}{x}
\end{scope}
\only<2>{\patchbars{0.0}{0.2}{2.2}}
\only<3->{
\node[blk,fill=dirc!40,draw=dirc] at (c2) {L2};
\node[blk,fill=dirc!40,draw=dirc] at (x2) {L2};
\draw[-{Stealth[length=6pt]},dirc,line width=1.5pt] (c2.south) to[bend left=25] node[right,font=\scriptsize,text=dirc] {copy} (x2.north);
\patchbars{0.0}{1.6}{0.6}
\node[card,anchor=north,text width=10cm,align=center,font=\small] at (1.5,-1.0)
  {Output recovers $\Rightarrow$ this component carries the information\\[2pt]
   {\footnotesize Path patching: patch only the path from one component into another}};
}
\end{tikzpicture}

\source{wang2022}

\note{
\begin{itemize}
\item The basic causal tool for circuits
\item Run the model on a clean prompt (answer: Mary) and a corrupted prompt that differs only in the relevant information (answer: John)
\item Copy one component's activation from the clean run into the corrupted run
\item If the output moves back towards Mary, that component carries the information that matters
\item Path patching refines this: only patch the effect of one component on another, to trace edges instead of nodes
\end{itemize}
}
\end{frame}

